std::queue<std::function<void()>> q;                 // command repository
std::mutex m; std::condition_variable cv;
void worker() {                                     // executor
    for (;;) {
        std::function<void()> cmd;
        { std::unique_lock lk(m); cv.wait(lk, [&]{ return !q.empty() || stop; });
          if (q.empty() && stop) return; cmd = std::move(q.front()); q.pop(); }
        cmd();                                       // run outside the lock
        history.push_back(cmd);                      // logging / undo
    }
}

